-- Latched binding revocations survive rapid revoke/regrant and out-of-order delivery.
CREATE TABLE group_expert_binding_revocations (
    conversation_id TEXT NOT NULL,
    source_agent_id TEXT NOT NULL,
    source_row_id BIGINT NOT NULL,
    before_revision BIGINT NOT NULL,
    PRIMARY KEY(conversation_id,source_agent_id,source_row_id)
);
CREATE FUNCTION group_expert_latch_binding(source_id TEXT, row_id BIGINT) RETURNS void LANGUAGE plpgsql AS $$ DECLARE item RECORD; cutoff BIGINT; operation TEXT; BEGIN FOR item IN SELECT s.conversation_id,s.revision FROM group_expert_scopes s,jsonb_array_elements(s.sources_json::jsonb) v WHERE v->>'source_agent_id'=source_id AND (v->>'source_row_id')::bigint=row_id LOOP cutoff:=item.revision+1; operation:='bindings:'||item.conversation_id||':'||source_id||':'||row_id||':'||cutoff; INSERT INTO group_expert_binding_revocations VALUES(item.conversation_id,source_id,row_id,cutoff) ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=GREATEST(group_expert_binding_revocations.before_revision,excluded.before_revision); INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) VALUES(operation,'invalidate','bindings:'||item.conversation_id,jsonb_build_object('domain_key','bindings:'||item.conversation_id,'revision',cutoff,'revocations',jsonb_build_array(jsonb_build_object('source_agent_id',source_id,'source_row_id',row_id,'before_revision',cutoff)))::text,operation,EXTRACT(EPOCH FROM now())::bigint) ON CONFLICT(operation_id) DO NOTHING; END LOOP; END; $$;
CREATE FUNCTION group_expert_binding_agent_update() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item RECORD; BEGIN IF OLD.enabled IS DISTINCT FROM NEW.enabled OR OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.kind IS DISTINCT FROM NEW.kind THEN FOR item IN SELECT a.agent_id,a.id FROM agents a WHERE a.id=OLD.id LOOP PERFORM group_expert_latch_binding(item.agent_id,item.id); END LOOP; END IF; RETURN NEW; END; $$;
CREATE TRIGGER group_expert_binding_agent_update BEFORE UPDATE ON agents FOR EACH ROW EXECUTE FUNCTION group_expert_binding_agent_update();
CREATE FUNCTION group_expert_binding_agent_delete() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item RECORD; BEGIN IF true THEN FOR item IN SELECT a.agent_id,a.id FROM agents a WHERE a.id=OLD.id LOOP PERFORM group_expert_latch_binding(item.agent_id,item.id); END LOOP; END IF; RETURN OLD; END; $$;
CREATE TRIGGER group_expert_binding_agent_delete BEFORE DELETE ON agents FOR EACH ROW EXECUTE FUNCTION group_expert_binding_agent_delete();
CREATE FUNCTION group_expert_binding_owner() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item RECORD; BEGIN IF OLD.source_user_id IS DISTINCT FROM NEW.source_user_id THEN FOR item IN SELECT a.agent_id,a.id FROM agents a WHERE a.user_id=OLD.source_user_id LOOP PERFORM group_expert_latch_binding(item.agent_id,item.id); END LOOP; END IF; RETURN NEW; END; $$;
CREATE TRIGGER group_expert_binding_owner BEFORE UPDATE ON expert_assignment_source FOR EACH ROW EXECUTE FUNCTION group_expert_binding_owner();
CREATE FUNCTION group_expert_binding_user() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item RECORD; BEGIN IF OLD.disabled IS DISTINCT FROM NEW.disabled OR OLD.role IS DISTINCT FROM NEW.role THEN FOR item IN SELECT a.agent_id,a.id FROM agents a WHERE a.user_id=OLD.id AND EXISTS(SELECT 1 FROM expert_assignment_source p WHERE p.source_user_id=OLD.id) LOOP PERFORM group_expert_latch_binding(item.agent_id,item.id); END LOOP; END IF; RETURN NEW; END; $$;
CREATE TRIGGER group_expert_binding_user BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION group_expert_binding_user();
CREATE FUNCTION group_expert_binding_department_update() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item RECORD; operation TEXT; BEGIN IF OLD.expert_ids IS DISTINCT FROM NEW.expert_ids THEN FOR item IN SELECT s.conversation_id,s.revision,a.agent_id,a.id FROM group_expert_scopes s,jsonb_array_elements(s.sources_json::jsonb) v,agents a WHERE s.department_id=OLD.scope_id AND v->>'source_agent_id'=a.agent_id AND (v->>'source_row_id')::bigint=a.id AND a.agent_id IN(SELECT jsonb_array_elements_text(OLD.expert_ids::jsonb) EXCEPT SELECT jsonb_array_elements_text(NEW.expert_ids::jsonb)) LOOP operation:='bindings:'||item.conversation_id||':'||item.agent_id||':'||item.id||':'||(item.revision+1); INSERT INTO group_expert_binding_revocations VALUES(item.conversation_id,item.agent_id,item.id,item.revision+1) ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=GREATEST(group_expert_binding_revocations.before_revision,excluded.before_revision); INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) VALUES(operation,'invalidate','bindings:'||item.conversation_id,jsonb_build_object('domain_key','bindings:'||item.conversation_id,'revision',item.revision+1,'revocations',jsonb_build_array(jsonb_build_object('source_agent_id',item.agent_id,'source_row_id',item.id,'before_revision',item.revision+1)))::text,operation,EXTRACT(EPOCH FROM now())::bigint) ON CONFLICT(operation_id) DO NOTHING; END LOOP; END IF; RETURN NEW; END; $$;
CREATE TRIGGER group_expert_binding_department_update BEFORE UPDATE ON department_resource_pools FOR EACH ROW EXECUTE FUNCTION group_expert_binding_department_update();
CREATE FUNCTION group_expert_binding_department_delete() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE item RECORD; operation TEXT; BEGIN IF true THEN FOR item IN SELECT s.conversation_id,s.revision,a.agent_id,a.id FROM group_expert_scopes s,jsonb_array_elements(s.sources_json::jsonb) v,agents a WHERE s.department_id=OLD.scope_id AND v->>'source_agent_id'=a.agent_id AND (v->>'source_row_id')::bigint=a.id AND a.agent_id IN(SELECT jsonb_array_elements_text(OLD.expert_ids::jsonb)) LOOP operation:='bindings:'||item.conversation_id||':'||item.agent_id||':'||item.id||':'||(item.revision+1); INSERT INTO group_expert_binding_revocations VALUES(item.conversation_id,item.agent_id,item.id,item.revision+1) ON CONFLICT(conversation_id,source_agent_id,source_row_id) DO UPDATE SET before_revision=GREATEST(group_expert_binding_revocations.before_revision,excluded.before_revision); INSERT INTO group_expert_outbox(operation_id,kind,target_id,payload,request_digest,created_at) VALUES(operation,'invalidate','bindings:'||item.conversation_id,jsonb_build_object('domain_key','bindings:'||item.conversation_id,'revision',item.revision+1,'revocations',jsonb_build_array(jsonb_build_object('source_agent_id',item.agent_id,'source_row_id',item.id,'before_revision',item.revision+1)))::text,operation,EXTRACT(EPOCH FROM now())::bigint) ON CONFLICT(operation_id) DO NOTHING; END LOOP; END IF; RETURN OLD; END; $$;
CREATE TRIGGER group_expert_binding_department_delete BEFORE DELETE ON department_resource_pools FOR EACH ROW EXECUTE FUNCTION group_expert_binding_department_delete();

UPDATE _schema_version SET version = 35;
